40	        return owner.getLastName() + ", " + owner.getFirstName();
41	    }
42	
43	    /**
44	     * Formats the owner's initials as the upper-cased first letters of firstName and
45	     * lastName, dot-separated with a trailing dot, e.g. {@code "J.S."}.
46	     */
47	    default String formatInitials(Owner owner) {
48	        return initial(owner.getFirstName()) + initial(owner.getLastName());
49	    }
50	
51	    /** The upper-cased first letter of {@code name} followed by a dot. */
52	    private String initial(String name) {
53	        return Character.toUpperCase(name.charAt(0)) + ".";
54	    }
55	
56	    /**
57	     * Derives the owner's locality (canonical region), preferring the postcode range over the
58	     * city-to-region table and yielding {@code "UNKNOWN"} when neither identifies a region.
59	     */
60	    default String resolveLocality(Owner owner) {
61	        return LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
62	    }
63	
64	    /**
65	     * Formats the owner's membership number as {@code "<customerCode>-M<YY>"}, where YY is the
66	     * last two digits of the registration date year, e.g. {@code "LON-SMI-0007-M26"}.
67	     */
68	    default String formatMembershipNumber(Owner owner) {
69	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
70	    }
