72	    /**
73	     * Resolves the owner's numeric membership level, assigned on creation: starts at {@code 1},
74	     * plus {@code 1} when an email is present, plus {@code 1} when the owner has no namesakes
75	     * (namesakeCount is 0), capped at {@code 3} (level {@code 4} is reserved for tenure).
76	     */
77	    default Integer resolveMembershipLevel(Owner owner) {
78	        int level = 1;
79	        if (hasEmail(owner)) {
80	            level++;
81	        }
82	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
83	            level++;
84	        }
85	        return Math.min(level, 3);
