322	    public String assignHousehold(Owner owner) throws DataAccessException {
323	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
324	        String householdId = members.stream()
325	            .map(Owner::getHouseholdId)
326	            .filter(Objects::nonNull)
327	            .findFirst()
328	            .orElseGet(() -> householdIdGenerator.generate(owner.getLastName(), owner.getAddress()));
329	        owner.setHouseholdId(householdId);
330	        for (Owner member : members) {
331	            if (member.getHouseholdId() == null) {
332	                member.setHouseholdId(householdId);
333	                ownerRepository.save(member);
334	            }
335	        }
336	        return householdId;
337	    }
