3	/**
4	 * Normalizes a telephone number to canonical E.164 form.
5	 *
6	 * <p>Formatting characters (spaces, dashes and brackets) are stripped. A number written with a
7	 * leading {@code '+'} keeps its explicit country code; otherwise the Australian country code
8	 * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
9	 * The result must carry between 8 and 15 digits after the {@code '+'} to be valid.
10	 */
11	public final class TelephoneNormalizer {
12	
13	    /** Minimum number of digits allowed after the leading {@code '+'} in E.164. */
14	    private static final int MIN_DIGITS = 8;
15	
16	    /** Maximum number of digits allowed after the leading {@code '+'} in E.164. */
17	    private static final int MAX_DIGITS = 15;
18	
19	    /** Country code assumed when the number carries no explicit {@code '+'} prefix. */
20	    private static final String DEFAULT_COUNTRY_CODE = "61";
21	
22	    private TelephoneNormalizer() {
23	    }
24	
25	    /**
26	     * Convert a raw telephone to E.164 form.
27	     *
28	     * @param telephone the raw telephone, possibly {@code null} or containing formatting characters
29	     * @return the E.164 string (a {@code '+'} followed by 8 to 15 digits), or {@code null} when the
30	     *         input cannot form a valid E.164 number
31	     */
32	    public static String toE164(String telephone) {
33	        if (telephone == null) {
34	            return null;
35	        }
36	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
37	        String digits;
38	        if (cleaned.startsWith("+")) {
39	            digits = cleaned.substring(1);
40	        } else {
41	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
42	            digits = DEFAULT_COUNTRY_CODE + national;
43	        }
44	        if (!digits.matches("\\d{" + MIN_DIGITS + "," + MAX_DIGITS + "}")) {
45	            return null;
46	        }
47	        return "+" + digits;
48	    }
49	}
