3	import java.util.Map;
4	import java.util.regex.Pattern;
5	
6	/**
7	 * Decides whether an owner's postcode is valid for its city.
8	 *
9	 * <p>A postcode is always four digits. When present it must fall within the inclusive range fixed
10	 * for the region derived from the owner's city ({@code NSW 2000-2099}, {@code VIC 3000-3099},
11	 * {@code QLD 4000-4099}); the region is resolved via {@link LocalityResolver}. A city whose region
12	 * is unknown accepts any four-digit postcode.
13	 */
14	public final class PostcodeRule {
15	
16	    /** A postcode is exactly four digits. */
17	    private static final Pattern FOUR_DIGITS = Pattern.compile("[0-9]{4}");
18	
19	    /** Region -> inclusive four-digit postcode range {@code {low, high}}. */
20	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
21	        "NSW", new int[] {2000, 2099},
22	        "VIC", new int[] {3000, 3099},
23	        "QLD", new int[] {4000, 4099});
24	
25	    private PostcodeRule() {
26	    }
27	
28	    /**
29	     * Resolve the region whose fixed postcode range contains {@code postcode}.
30	     *
31	     * @param postcode the owner's postcode, possibly {@code null}
32	     * @return the canonical region string whose inclusive range contains the four-digit
33	     *         {@code postcode}, or {@code null} when the postcode is absent, malformed, or in no
34	     *         known range
35	     */
36	    public static String regionForPostcode(String postcode) {
37	        if (postcode == null || !FOUR_DIGITS.matcher(postcode).matches()) {
38	            return null;
39	        }
40	        int value = Integer.parseInt(postcode);
41	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
42	            int[] range = entry.getValue();
43	            if (value >= range[0] && value <= range[1]) {
44	                return entry.getKey();
45	            }
46	        }
47	        return null;
48	    }
49	
50	    /**
51	     * Whether {@code postcode} is acceptable for {@code city}.
52	     *
53	     * @param city     the owner's city, possibly {@code null}
54	     * @param postcode the owner's postcode; {@code null} means "not supplied"
55	     * @return {@code true} when the postcode is absent, or is four digits within the range for the
56	     *         city's region, or is four digits and the city has no known region; {@code false} for a
57	     *         malformed postcode or one outside its region's range
58	     */
59	    public static boolean isValid(String city, String postcode) {
60	        if (postcode == null) {
61	            return true;
62	        }
63	        if (!FOUR_DIGITS.matcher(postcode).matches()) {
64	            return false;
65	        }
66	        int[] range = REGION_POSTCODES.get(LocalityResolver.resolve(city));
67	        if (range == null) {
68	            return true;
69	        }
70	        int value = Integer.parseInt(postcode);
71	        return value >= range[0] && value <= range[1];
72	    }
73	}
