18	    /** Locality returned for any city not present in {@link #CITY_REGION}. */
19	    public static final String UNKNOWN = "UNKNOWN";
20	
21	    /** City -> canonical region; anything not listed derives {@link #UNKNOWN}. */
22	    private static final Map<String, String> CITY_REGION = Map.of(
23	        "Sydney", "NSW",
24	        "Melbourne", "VIC",
25	        "Brisbane", "QLD");
26	
27	    private LocalityResolver() {
28	    }
29	
30	    /**
31	     * Resolve the canonical region, preferring the postcode over the city.
32	     *
33	     * @param city     the owner's city, possibly {@code null}
34	     * @param postcode the owner's postcode, possibly {@code null}
35	     * @return the region whose range contains the postcode; otherwise the region derived from the
36	     *         city via {@link #resolve(String)} (which yields {@code "UNKNOWN"} for an unknown city)
37	     */
38	    public static String resolve(String city, String postcode) {
